);

const browser = await chromium.launch({ executablePath: '/nix/store/zi4f80l169xlmivz8vja8wlphq74qqk0-chromium-125.0.6422.141/bin/chromium' });
const page = await browser.newPage({ viewport: { width: 390, height: 844 } });
page.on('pageerror', e => console.log('[pageerror]', e.message));
page.on('console', m => { if (m.type() === 'error') console.log('[console.error]', m.text().slice(0, 200)); });
await page.addInitScript(t => localStorage.setItem('authToken', t), token);

await page.goto('http://localhost:5000/trades/terminal?quick=1', { waitUntil: 'networkidle' });
await page.waitForTimeout(4000);

const info = await page.evaluate(() => {
  const kps = [...document.querySelectorAll('.tp-kp')];
  const layers = [...document.querySelectorAll('.tp-layer')];
  const first = kps[0];
  const chain = [];
  let el = first;
  while (el && el !== document.body) {
    const cs = getComputedStyle(el);
    chain.push({
      tag: el.tagName + '.' + String(el.className).split(' ').slice(0, 2).join('.'),
      display: cs.display, opacity: cs.opacity, visibility: cs.visibility,
      transform: cs.transform === 'none' ? 'none' : cs.transform.slice(0, 60),
      animation: cs.animationName, w: el.offsetWidth, h: el.offsetHeight,
    });
    el = el.parentElement;
  }
  return {
    kpCount: kps.length,
    layerCount: layers.length,
    firstRect: first ? first.getBoundingClientRect().toJSON() : null,
    chain,
  };
});
console.log(JSON.stringify(info, null, 1));
await page.screenshot({ path: '/tmp/claude-1000/-home-runner-workspace/c9d2317c-7d0c-4569-abe8-6b78546105d8/scratchpad/shots/debug-terminal.png' });
