import { chromium } from '/home/runner/workspace/node_modules/playwright/index.mjs';
import jwt from '/home/runner/workspace/node_modules/jsonwebtoken/index.js';
const token = jwt.sign({ userId: 22, email: 'oliverharryleonard@gmail.com', merchantId: 22, role: 'merchant' }, process.env.JWT_SECRET || 'dev-only-jwt-secret-not-for-production', { expiresIn: '1h' });
const browser = await chromium.launch({ executablePath: '/nix/store/zi4f80l169xlmivz8vja8wlphq74qqk0-chromium-125.0.6422.141/bin/chromium' });
const page = await browser.newPage({ viewport: { width: 700, height: 900 } });
page.on('pageerror', e => console.log('[pageerror]', e.message));
await page.addInitScript(t => localStorage.setItem('authToken', t), token);

// column width = widest direct child of body's root that's < viewport
const colWidth = () => page.evaluate(() => {
  const els = [...document.querySelectorAll('div,main,section')].filter(e => {
    const r = e.getBoundingClientRect();
    return r.width > 300 && r.width < 500 && r.height > 400;
  });
  const w = els.map(e => Math.round(e.getBoundingClientRect().width));
  return w.length ? Math.max(...w) : null;
});

for (const [name, url] of [
  ['tenant-directory', '/property/tenants'],
  ['recurring', '/trades/recurring'],
  ['client-profile-direct', null], // filled below
]) { /* placeholder */ break; }

const results = {};
for (const [name, url] of [
  ['property-dash', '/property'], ['tenant-directory', '/property/tenants'],
  ['trades-clients', '/trades/clients'], ['recurring', '/trades/recurring'],
  ['smart-terminal', '/smart-terminal'],
]) {
  await page.goto('http://localhost:5000' + url, { waitUntil: 'networkidle' });
  await page.waitForTimeout(1200);
  results[name] = await colWidth();
}
// directory → profile via click (the reported narrowing)
await page.goto('http://localhost:5000/property/tenants', { waitUntil: 'networkidle' });
await page.click('text=isla murphy');
await page.waitForSelector('text=16 beach rd', { timeout: 15000 });
await page.waitForTimeout(800);
results['tenant-profile-via-click'] = await colWidth();
await page.screenshot({ path: 'shots/w-tenant-profile.png' });
await page.goto('http://localhost:5000/trades/clients', { waitUntil: 'networkidle' });
await page.click('text=prod ready');
await page.waitForSelector('text=1 production way', { timeout: 15000 });
await page.waitForTimeout(800);
results['client-profile-via-click'] = await colWidth();
console.log(JSON.stringify(results, null, 1));
await browser.close();
EOF
