import { chromium } from '/home/runner/workspace/node_modules/playwright/index.mjs';
import jwt from '/home/runner/workspace/node_modules/jsonwebtoken/index.js';
const token = jwt.sign({ userId: 22, email: 'oliverharryleonard@gmail.com', merchantId: 22, role: 'merchant' }, process.env.JWT_SECRET || 'dev-only-jwt-secret-not-for-production', { expiresIn: '1h' });
const browser = await chromium.launch({ executablePath: '/nix/store/zi4f80l169xlmivz8vja8wlphq74qqk0-chromium-125.0.6422.141/bin/chromium' });
const page = await browser.newPage({ viewport: { width: 1280, height: 900 } });
await page.addInitScript(t => localStorage.setItem('authToken', t), token);

const routes = ['/dashboard','/transactions','/stock','/settings','/nfc','/board-builder','/smart-terminal',
  '/property','/property/tenants','/property/analytics','/property/terminal',
  '/trades','/trades/clients','/trades/analytics','/trades/terminal','/trades/quote','/trades/recurring'];

for (const r of routes) {
  await page.goto('http://localhost:5000' + r, { waitUntil: 'networkidle' }).catch(() => {});
  await page.waitForTimeout(1200);
  const gutter = await page.evaluate(() => {
    // sample the effective background at a gutter point (x=60, y=450)
    let el = document.elementFromPoint(60, 450);
    while (el) {
      const bg = getComputedStyle(el).backgroundColor;
      if (bg && bg !== 'rgba(0, 0, 0, 0)' && bg !== 'transparent') return bg + ' <- ' + (el.tagName + '.' + String(el.className).slice(0, 30));
      el = el.parentElement;
    }
    return 'body:' + getComputedStyle(document.body).backgroundColor;
  });
  console.log(r.padEnd(22), gutter);
}
await browser.close();
EOF
